;; curriculum: Calc-1 (gr 12 / undergrad) — accumulation function; prerequisites: area
;; math target: the hill's height at x is the accumulated area under the bump up to x: F(x) = ∫ₐˣ f(t) dt.

app riya-level-accum "1.1.0"
"riya level 21 · Accumulation — the hill climbs fastest where the dashed bump is tallest. Slide the bump and watch the inflection point move; grow the bump and feel the hill steepen. Skate the accumulating hill — catch 5 ★! Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup + std-tutorial-overlay, rendered through math-canvas so the axes and the world's own function stay visible. Rebound into the riya-game-platformer organism (menu + all eighteen worlds)."

;; @exposure internal

orbital RiyaAccumOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaAccumBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaAccumPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaAccumFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaAccumPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaAccumCurveSample = {
    x : number!
    y : number!
  }
  type RiyaAccumCurve = {
    label : string
    color : string
    samples : [RiyaAccumCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaAccumCurveMod = {
    id : string!
    x0 : number!
    x1 : number!
    a : number!
    h : number!
    k : number!
  }
  type RiyaAccumFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }

  entity RiyaAccumState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaAccumBody = { x: -9, y: 2.2, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaAccumPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaAccumFx] = []
    celebrated : boolean = false
    seq : number = 0
    lastText : string = ""
    zoneId : string = "accum"
    platforms : [RiyaAccumPlatform] = []
    curves : [RiyaAccumCurve] = []
  }

  entity AccumTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait AccumBody = Body.traits.PlatformerBody -> RiyaAccumState {
    events {
      STEER: ACCUM_STEER
      JUMP: ACCUM_LEAP
      PLACE: ACCUM_PLACE
      RESTART: ACCUM_RESTART
      SET_PLATFORMS: ACCUM_SET_PLATFORMS
      SET_SKATE_CURVE: ACCUM_SET_SKATE_CURVE
      BODY_MOVED: ACCUM_MOVED
      BODY_JUMPED: ACCUM_JUMPED
      BODY_LANDED: ACCUM_LANDED
      BODY_HAZARD: ACCUM_HAZARD
      BODY_GOAL: ACCUM_GOAL
      BODY_FELL: ACCUM_FELL
      BODY_SKATE_START: ACCUM_SKATE_ON
      BODY_SKATE_END: ACCUM_SKATE_OFF
    }
    config {
      running: true
      spawn: { x: -9, y: 2.2, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      curveModsEnabled: true
      skateSnap: 0.9
    }
  }

  trait AccumGate = Gate.traits.ObjectiveFlow -> RiyaAccumState {
    events {
      PROGRESS: ACCUM_PROGRESS
      GAME_END: ACCUM_GAME_END
      RESTART: ACCUM_RESTART
    }
    config { running: true }
  }

  trait AccumFx = Particles.traits.FxParticles -> RiyaAccumState {
    events {
      BURST: ACCUM_BURST
    }
    config { running: true }
  }

  trait AccumTutorialPreview -> AccumTutorialData [interaction, instance] {
    initial: idle
    state idle {
      INIT -> idle
        (render-ui center null)
    }
  }

  trait AccumTutorial = Tutorial.traits.TutorialOverlay -> AccumTutorialData {
    events {
      SHOW: ACCUM_TUTORIAL_SHOW
      TUTORIAL_DONE: ACCUM_TUTORIAL_DONE
    }
    config {
      autoShow: true
      previewTrait: @trait.AccumTutorialPreview
      steps: [
        { id: "intro", title: "Accumulation", body: "The solid hill is the accumulation of the dashed bump. Where the bump is tall, the hill steepens. Slide or grow the bump to reshape the hill." }
      ]
    }
  }

  trait AccumPickup = Pickup.traits.Pickup -> RiyaAccumState {
    events {
      PICKED: ACCUM_PICKED
      COLLECT: ACCUM_COLLECT
      PICKUP_SET_COMPLETED: ACCUM_PICKUP_SET_COMPLETED
      SET_FEATURES: ACCUM_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }

  trait AccumLevelData -> @rebindable RiyaAccumState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "accum"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn c @c))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          curveMods: (array/map @config.curveMods (fn m @m))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaAccumPlatform]!
        stars : [RiyaAccumPickup]!
        skateCurve : [RiyaAccumCurveSample]
        curveOverlay : [RiyaAccumCurve]
        curveMods : [RiyaAccumCurveMod]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
