        @tier "presentation"
      equation : string = "y = F(x)"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "accumulation: the hill climbs fastest where the dashed bump is tallest — its height collects the bump"
        @label "Concept"
