        @tier "domain"
      platforms : [RiyaAccumPlatform] = [
        { id: "b0", x: -9.6, y: -2, width: 1.6, height: 3.1, type: "ground" }
        { id: "b1", x: -8, y: -2, width: 1.6, height: 3.1, type: "ground" }
