  trait RiyaAccumPlay -> @rebindable RiyaAccumState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.celebrated false)
        (set @entity.score 0)
        (emit ACCUM_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "ACCUM_LEFT", KeyA: "ACCUM_LEFT", ArrowRight: "ACCUM_RIGHT", KeyD: "ACCUM_RIGHT", ArrowUp: "ACCUM_JUMP", KeyW: "ACCUM_JUMP", Space: "ACCUM_JUMP" }
            keyUpMap: { ArrowLeft: "ACCUM_STOP", KeyA: "ACCUM_STOP", ArrowRight: "ACCUM_STOP", KeyD: "ACCUM_STOP" }
            curves: (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "star") @config.starColor "#f472b6"), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (array/concat
                    (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] [])
                    []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })
        (render-ui hud-bottom {
          type: stack
          direction: horizontal
          justify: start
          className: "p-4"
          children: [ { type: control-grid, kind: "dpad", visibility: "auto", directionEvents: { left: "ACCUM_LEFT", right: "ACCUM_RIGHT", up: "ACCUM_JUMP" }, directionReleaseEvents: { left: "ACCUM_STOP", right: "ACCUM_STOP" } } ]
        })

      RIYA_LEVEL_DATA -> idle when (== @payload.id "accum")
        (set @entity.curves @payload.curveOverlay)
        (set @entity.objectivesLeft (array/len @payload.stars))
        (emit ACCUM_SET_PLATFORMS { platforms: @payload.platforms })
        (emit ACCUM_SET_SKATE_CURVE { curve: @payload.skateCurve })
        (emit ACCUM_SET_FEATURES { features: @payload.stars })

      ACCUM_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit ACCUM_STEER { dir: -1 })

      ACCUM_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit ACCUM_STEER { dir: 1 })

      ACCUM_STOP -> idle when (== @entity.active true)
        (emit ACCUM_STEER { dir: 0 })

      ACCUM_JUMP -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit ACCUM_LEAP {})

      ACCUM_FELL -> idle when (== @entity.active true)
        (emit ACCUM_PLACE { x: @config.respawnX, y: @config.respawnY })
        (emit ACCUM_BURST { particles: (array/map [ "fx-accum-fell" ] (fn fid { id: @fid, type: "info", x: @config.respawnX, z: @config.respawnY, message: "💫", ttl: 3 })) })

      ACCUM_SKATE_ON -> idle when (== @entity.active true)
        (emit ACCUM_BURST { particles: (array/concat
          { id: "narrative-skate", type: "narrative", x: @entity.body.x, z: (+ @entity.body.y 2), y: 0, message: "hill climbs fastest here", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
          {
            id: "fx-accum-skate",
            type: "info",
            x: @payload.x,
            z: (+ @payload.y 0.6),
            y: 0,
            message: (str/concat @config.equationText " · x = " (math/round (+ @payload.x 0.3) 1)),
            ttl: 4
          }
        ) })
      ACCUM_PICKED -> idle when (== @entity.active true)
        (emit ACCUM_BURST { particles: (array/map [ "fx-pickup-" ] (fn fid { id: (str/concat @fid @payload.id), type: "pickup", x: @payload.x, z: @payload.y, message: (object/get @payload glyph), ttl: 2 })) })
      ACCUM_COLLECT -> idle when (== @entity.active true)
        (set @entity.score @payload.total)
        (set @entity.objectivesLeft (- (array/len @entity.pickups) @payload.total))
        (emit ACCUM_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })

      ACCUM_PICKUP_SET_COMPLETED -> idle when (== @entity.active true)
        (emit ACCUM_BURST { particles: (array/map [ "complete" ] (fn _ { id: "narrative-complete", type: "narrative", x: 0, z: 8, y: 0, message: "the hill is the integral of the bump", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#facc15", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
        (emit ACCUM_PROGRESS { objectivesLeft: 0, movesLeft: 9999 })
      ACCUM_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "accum" })

      ACCUM_TUTORIAL_DONE -> idle
        (emit ACCUM_BURST { particles: (array/map [ "tutorial" ] (fn _ { id: "narrative-tutorial", type: "narrative", x: 0, z: 10, y: 0, message: "the hill collects the bump: F(x) = ∫ₐˣ f(t) dt", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
    }

    ticks {
      renderTick every 100ms when (== @entity.active true)
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
