    state idle {
      ACCUM_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (str/endsWith @payload.id "slide")
          (emit ACCUM_CURVE_MOD_ADD { x0: -4, x1: 2, a: 1, h: -2, k: 0 })
          (if (str/endsWith @payload.id "grow")
            (emit ACCUM_CURVE_MOD_ADD { x0: -2, x1: 4, a: 1.3, h: 0, k: 0 })
            null))
        (if (== @payload.kind "phase")
          (emit ACCUM_BURST { particles: [ { id: "narrative-phase", type: "narrative", x: @payload.x, z: (+ @payload.y 1.5), y: 0, message: "f(x−h)", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 } ] })
          (if (== @payload.kind "tilt")
            (emit ACCUM_BURST { particles: [ {
              id: "narrative-tilt",
              type: "narrative",
              x: @payload.x,
              z: (+ @payload.y 1.5),
              y: 0,
              message: "a·f(x)",
              ttl: 2,
              maxTtl: 2,
              bornAt: (time/now),
              space: "world",
              effect: "float-text",
              color: "#f472b6",
              size: 0.7,
              vx: 0,
              vy: 0,
              vz: 0,
              particleCount: 1
            } ] })
            null))
    }

    emits {
      ACCUM_CURVE_MOD_ADD -> external {
        x0 : number!
        x1 : number!
        a : number!
        h : number!
        k : number!
      }
        @description "Renamed CURVE_MOD_ADD consumed by the platformer-body authority; phase/tilt pads reshape the hill."
        @tier "domain"
      ACCUM_BURST -> external {
        particles : [RiyaAccumFx]
      }
        @description "Particle batch spawned for the phase/tilt narrative beats; fx-particles fades it."
        @tier "domain"
    }

    listens {
      ACCUM_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "accum"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaAccumClear -> @rebindable RiyaAccumState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "ACCUM_NEXT", variant: "primary" } ]
        })

      ACCUM_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      ACCUM_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-accum"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Accumulation clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "The hill was steepest exactly where the bump peaked — height accumulates slope."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-accum" as RiyaAccumPage -> AccumLevelData, AccumBody, AccumGate, AccumFx, AccumPickup, AccumTutorial, RiyaAccumGenre, RiyaAccumPlay, AccumChallenge, RiyaAccumClear
}
